/** Deep Field 3D — §5 UI screens. Each renders a 1920×1080 frame from sim data. */
const ic = (n, cls = '', size = 0) => `<span class="icon ${cls}"${size ? ` style="width:${size}px;height:${size}px"` : ''}><img src="game/assets/ui/icon_${n}.svg" alt=""></span>`;
const bar = (pct, cls = '', extra = '') => `<div class="bar ${cls}" ${extra}><i style="width:${pct}%"></i></div>`;
const kbd = (k) => `<kbd class="key">${k}</kbd>`;
const tag = (t, cls = '') => `<span class="tag ${cls}">${t}</span>`;
const pips = (lvl, bps = [3, 7, 10]) => `<div class="pips">${Array.from({ length: 10 }, (_, i) => `<i class="${i < lvl ? (bps.includes(i + 1) ? 'bp' : 'on') : ''}"></i>`).join('')}</div>`;
const world = (extra = '') => `<div class="world">${extra}<div class="horizon"></div><div class="silhouette" style="left:8%;width:180px;height:220px"></div><div class="silhouette" style="left:22%;width:60px;height:340px"></div><div class="silhouette" style="right:12%;width:260px;height:160px"></div><div class="silhouette" style="right:30%;width:40px;height:300px"></div></div>`;
const panel = (title, body, { tone = '', hazard = false, ft = '', style = '', cls = '' } = {}) => `<section class="panel ${cls}" style="${style}"><div class="hd ${tone} ${hazard ? 'hazard' : ''}"><span class="ic"></span><h3>${title}</h3></div><div class="bd">${body}</div>${ft ? `<div class="ft">${ft}</div>` : ''}</section>`;

const TOWERS = [
  { id: 'lance', name: 'Lance', cost: 100, tag: 'ground · wall', hue: '#2b5cff', desc: 'Hitscan rail. Single target, pierce at L10.' },
  { id: 'nova', name: 'Nova', cost: 140, tag: 'ground', hue: '#f0c83a', desc: 'Mortar splash 3.2 m. Burn at L7.' },
  { id: 'arc', name: 'Arc', cost: 160, tag: 'ground · wall', hue: '#f05ae6', desc: 'Chain shock, 1 hop. Flash Freeze fuel.' },
  { id: 'singularity', name: 'Singularity', cost: 180, tag: 'ground', hue: '#9b5be8', desc: 'Chill aura 6 m. Thermal Shock half.' },
  { id: 'skywatch', name: 'Skywatch', cost: 120, tag: 'ground · wall', hue: '#22d3ee', desc: 'Air only. Flak proximity fuse.' },
  { id: 'barricade', name: 'Barricade', cost: 60, tag: 'barricade', hue: '#e9614c', desc: 'Closes the cut. Forces the long route.' },
];
const ENEMIES = ['drifter', 'mote', 'monolith', 'skiff', 'aegis', 'warden', 'mole', 'cluster'];
const FACTIONS = [
  { id: 'forge', name: 'Forge', ability: 'Overdrive', passive: '−10% build cost', cd: 30, r: 10, hue: 'var(--brass-400)' },
  { id: 'ember', name: 'Ember', ability: 'Ignition Wave', passive: '+30% burn duration', cd: 22, r: 6, hue: 'var(--el-fire)' },
  { id: 'tempest', name: 'Tempest', ability: 'Chain Surge', passive: '+12% fire rate', cd: 26, r: 7, hue: 'var(--el-arcane)' },
];

/* ── shared HUD chrome ─────────────────────────────────────────────── */
function hudTop({ wave = 4, total = 10, phase = 'ACTIVE', timer = '0:42', lives = 3, alive = 17 } = {}) {
  return `<div class="abs" style="left:0;right:0;top:0;height:var(--hud-topbar-h);display:flex;align-items:center;justify-content:center;gap:var(--space-8);padding:0 var(--hud-edge)">
    <div class="glass row" style="padding:8px 18px;clip-path:var(--clip-notch-top);box-shadow:inset 0 0 0 1px var(--border-panel);gap:var(--space-7)">
      <div class="col" style="gap:2px;align-items:center"><span class="label">Wave</span><span class="numeral" style="color:${phase === 'ACTIVE' ? 'var(--wave-active)' : 'var(--wave-idle)'}">${String(wave).padStart(2, '0')}<span style="font-size:var(--size-stat-sm);color:var(--text-muted)">/${total}</span></span></div>
      <div class="rule" style="width:1px;height:36px"></div>
      <div class="col" style="gap:2px"><span class="label">${phase}</span><span class="stat mono">${timer}</span>
        <div class="row" style="gap:3px">${Array.from({ length: total }, (_, i) => `<i style="width:10px;height:4px;background:${i < wave - 1 ? 'var(--venom-500)' : i === wave - 1 ? 'var(--wave-active)' : 'var(--obsidian-500)'}"></i>`).join('')}</div></div>
      <div class="rule" style="width:1px;height:36px"></div>
      <div class="col" style="gap:2px"><span class="label">Alive</span><span class="stat mono">${alive}</span></div>
      <div class="col" style="gap:2px;align-items:center"><span class="label">Core</span><div class="row" style="gap:4px">${[0, 1, 2].map((i) => `<i style="width:14px;height:14px;transform:rotate(45deg);background:${i < lives ? 'var(--lives)' : 'var(--obsidian-500)'};box-shadow:${i < lives ? '0 0 8px var(--lives)' : 'none'}"></i>`).join('')}</div></div>
    </div></div>`;
}
function hudVitals({ hp = 74, shield = 0, faction = 'ember', ability = 'Ignition Wave', cd = 0 } = {}) {
  const f = FACTIONS.find((x) => x.id === faction);
  return `<div class="abs" style="left:var(--hud-edge);bottom:var(--hud-edge);width:420px">
    <div class="glass" style="padding:14px 16px;box-shadow:inset 0 0 0 1px var(--border-panel);clip-path:var(--clip-chamfer)">
      <div class="row" style="gap:14px;align-items:stretch">
        <div style="width:72px;height:72px;background:var(--surface-slot);box-shadow:inset 0 0 0 1px ${cd ? 'var(--border-strong)' : 'var(--brass-500)'},${cd ? 'none' : 'var(--glow-brass)'};clip-path:var(--clip-chamfer-sm);position:relative;display:grid;place-items:center">
          ${ic('ability_' + ability.toLowerCase().replace(' ', ''), cd ? 'dim' : 'brass')}
          ${cd ? `<div class="abs" style="inset:0;background:conic-gradient(rgba(8,11,17,.75) ${cd}%,transparent 0)"></div><span class="abs mono" style="bottom:4px;right:6px;font:var(--weight-bold) var(--size-caption)/1 var(--font-mono)">${Math.round(f.cd * cd / 100)}s</span>` : ''}
          <span class="abs" style="left:4px;top:3px;font:var(--weight-bold) 10px/1 var(--font-mono);color:var(--text-muted)">Q</span>
        </div>
        <div class="grow col" style="gap:6px;justify-content:center">
          <div class="row between"><span class="row" style="gap:6px"><span class="faction ${faction}"></span><span class="label" style="color:var(--text-secondary)">${f.name} · ${ability}</span></span><span class="mono" style="font-size:var(--size-caption);color:var(--text-muted)">${f.passive}</span></div>
          <div class="row between"><span class="label">HP</span><span class="mono" style="font-size:var(--size-caption)">${hp}/100</span></div>${bar(hp, hp <= 30 ? 'tall low' : 'tall')}
          ${shield ? `<div class="row between"><span class="label">Shield</span><span class="mono" style="font-size:var(--size-caption)">${shield}/25</span></div>${bar(shield * 4, 'shield')}` : ''}
        </div></div></div></div>`;
}
function hudEconomy({ scrap = 340, alloy = 6, flux = 3, plating = 2, gravium = 0 } = {}) {
  return `<div class="abs" style="left:var(--hud-edge);top:var(--hud-edge)">
    <div class="glass col" style="padding:10px 14px;gap:8px;box-shadow:inset 0 0 0 1px var(--border-panel);clip-path:var(--clip-chamfer)">
      <div class="row" style="gap:10px"><i style="width:12px;height:12px;transform:rotate(45deg);background:var(--res-gold);box-shadow:0 0 8px var(--res-gold)"></i><span class="numeral brass" style="font-size:28px">${scrap}</span><span class="label">Scrap</span></div>
      <div class="rule"></div>
      <div class="row" style="gap:14px">${[['alloy', alloy], ['flux', flux], ['plating', plating], ['gravium', gravium]].map(([k, v]) => `<span class="row" style="gap:5px">${ic('scrap_' + k, v ? '' : 'dim')}<span class="mono" style="font-size:var(--size-caption);color:${v ? 'var(--text-primary)' : 'var(--text-disabled)'}">${v}</span></span>`).join('')}</div>
    </div></div>`;
}
function hudLoadout({ weapon = 'rifle', ammoType = 'standard', mag = 18, magMax = 24, reserve = 96, alt = 'MARK', altReady = true, slots = ['sidearm', 'rifle'], sel = 1 } = {}) {
  return `<div class="abs" style="right:var(--hud-edge);bottom:var(--hud-edge);width:420px">
    <div class="glass" style="padding:14px 16px;box-shadow:inset 0 0 0 1px var(--border-panel);clip-path:var(--clip-chamfer)">
      <div class="row" style="gap:14px;align-items:stretch">
        <div class="grow col" style="gap:6px;justify-content:center;align-items:flex-end;text-align:right">
          <div class="row" style="gap:8px"><span class="label" style="color:var(--text-secondary)">${weapon}</span>${ic('weapon_' + weapon)}</div>
          <div class="row" style="gap:10px;align-items:baseline"><span class="numeral" style="font-size:44px">${mag}</span><span class="stat mono muted">/ ${reserve}</span></div>
          <div style="width:100%">${bar(mag / magMax * 100, 'seg thin', `style="--n:${magMax}"`)}</div>
          <div class="row" style="gap:8px">${ic('ammo_' + ammoType)}<span class="label">${ammoType}</span><span class="rule" style="width:1px;height:14px"></span><span class="label" style="color:${altReady ? 'var(--text-arcane)' : 'var(--text-disabled)'}">RMB · ${alt}</span></div>
        </div>
        <div class="col" style="gap:6px">${slots.map((s, i) => `<div class="slot ${i === sel ? 'sel' : ''}" style="width:52px;height:52px"><span class="k">${i + 1}</span>${ic('weapon_' + s, i === sel ? 'arc' : 'dim')}</div>`).join('')}<div class="slot" style="width:52px;height:52px"><span class="k">3</span>${ic('weapon_wrench', 'dim')}</div></div>
      </div></div></div>`;
}
function hudTeam(states = [['forge', 'Kestrel', 92, 0], ['tempest', 'Vane', 41, 12]]) {
  return `<div class="abs col" style="left:var(--hud-edge);top:140px;gap:8px;width:230px">${states.map(([f, n, hp, sh]) => `<div class="glass row" style="padding:8px 10px;gap:10px;box-shadow:inset 0 0 0 1px ${hp === 0 ? 'var(--threat-500)' : 'var(--border-panel)'};clip-path:var(--clip-chamfer-sm)"><span class="faction ${f}"></span><div class="grow col" style="gap:4px"><div class="row between"><span style="font:var(--weight-semibold) var(--size-caption)/1 var(--font-display)">${n}</span><span class="label" style="color:${hp === 0 ? 'var(--state-danger)' : 'var(--text-muted)'}">${hp === 0 ? 'DOWNED' : hp + '%'}</span></div>${bar(hp, hp <= 30 ? 'thin low' : 'thin')}${sh ? bar(sh * 4, 'thin shield') : ''}</div></div>`).join('')}</div>`;
}
function hudToasts(items = [['<b>Vane</b> built Arc at g4', ''], ['<b>Thermal Shock</b> ×3 — 84 dmg', 'brass'], ['<b>Wave 4</b> · Skiffs inbound — air lane', 'dan']]) {
  return `<div class="abs col" style="right:var(--hud-edge);top:140px;gap:6px;align-items:flex-end">${items.map(([t, c]) => `<div class="toast ${c}">${t}</div>`).join('')}</div>`;
}
function crosshair(state = 'default') {
  const gap = state === 'shielded' ? 10 : 7, col = { default: 'var(--steel-050)', shielded: 'var(--arcane-400)', armored: 'var(--steel-300)', burrowed: 'var(--ember-400)', hit: 'var(--brass-300)', mark: 'var(--brass-400)' }[state];
  const arms = [[`left:50%;top:0;width:2px;height:${20 - gap}px;margin-left:-1px`], [`left:50%;bottom:0;width:2px;height:${20 - gap}px;margin-left:-1px`], [`top:50%;left:0;height:2px;width:${20 - gap}px;margin-top:-1px`], [`top:50%;right:0;height:2px;width:${20 - gap}px;margin-top:-1px`]];
  let extra = '';
  if (state === 'shielded') extra = `<div class="abs" style="left:50%;top:50%;width:34px;height:34px;transform:translate(-50%,-50%) rotate(45deg);border:2px solid ${col};opacity:.8"></div>`;
  if (state === 'armored') extra = `<div class="abs" style="left:50%;top:50%;width:28px;height:28px;transform:translate(-50%,-50%);border:2px solid ${col};clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%)"></div>`;
  if (state === 'burrowed') extra = `<div class="abs" style="left:50%;top:50%;width:44px;height:44px;transform:translate(-50%,-50%);border:2px dashed ${col};border-radius:50%;opacity:.8"></div><span class="abs label" style="left:50%;top:30px;transform:translateX(-50%);color:${col};white-space:nowrap">UNTARGETABLE</span>`;
  if (state === 'hit') extra = `<div class="abs" style="left:50%;top:50%;width:26px;height:26px;transform:translate(-50%,-50%) rotate(45deg);border:2px solid ${col}"></div>`;
  if (state === 'mark') extra = `<div class="abs" style="left:50%;top:50%;width:36px;height:36px;transform:translate(-50%,-50%);border:2px solid ${col};border-radius:50%;border-left-color:transparent;border-right-color:transparent"></div>`;
  return `<div class="crosshair">${arms.map(([s]) => `<i style="${s};background:${col}"></i>`).join('')}<i style="left:50%;top:50%;width:2px;height:2px;margin:-1px 0 0 -1px;background:${col}"></i>${extra}</div>`;
}
function overhead({ hp = 70, shield = 0, status = [], name = '', elite = '', x, y, scale = 1 }) {
  return `<div class="abs overhead" style="left:${x}px;top:${y}px;transform:translate(-50%,-100%) scale(${scale})">
    ${elite ? `<span class="elite ${elite}">${elite}</span>` : ''}${name ? `<span class="label" style="color:var(--text-secondary)">${name}</span>` : ''}
    ${status.length ? `<div class="row" style="gap:3px">${status.map((s) => `<span style="width:16px;height:16px;background:var(--surface-scrim);box-shadow:inset 0 0 0 1px var(--border-strong);display:grid;place-items:center">${ic('status_' + s, '', 12)}</span>`).join('')}</div>` : ''}
    <div class="hp">${bar(hp, hp <= 30 ? 'thin low' : 'thin')}${shield ? bar(shield, 'thin shield') : ''}</div></div>`;
}

export const SCREENS = [];
const S = (o) => SCREENS.push(o);

/* ── In-match HUD ──────────────────────────────────────────────────── */
S({ id: 'hud', group: 'In-match', label: 'HUD — full', tag: '1080p', note: 'Four clusters: vitals + faction ability (bottom-left), loadout (bottom-right), economy (top-left), wave (top-centre). Teammate strip under economy, toast feed under wave, world overheads in the field. Every numeral is Mono, tabular.',
  render: () => `${world()}${overhead({ x: 900, y: 470, hp: 62, status: ['burn', 'chill'], scale: 1 })}${overhead({ x: 1180, y: 430, hp: 100, shield: 80, name: 'Warden', scale: .9 })}${overhead({ x: 700, y: 520, hp: 100, name: 'Monolith', elite: 'juggernaut', scale: 1.1 })}${overhead({ x: 1050, y: 380, hp: 40, status: ['mark'], scale: .7 })}<div class="scrim-top"></div><div class="scrim-bottom"></div>${hudTop()}${hudEconomy()}${hudTeam()}${hudToasts()}${hudVitals()}${hudLoadout()}${crosshair('default')}
  <div class="abs" style="left:50%;bottom:150px;transform:translateX(-50%)" ><div class="toast brass">${kbd('E')} <b>Build</b> · socket g4 · ground</div></div>` });

S({ id: 'crosshairs', group: 'In-match', label: 'Crosshair states', tag: '6', note: 'Default, shielded (arcane diamond — burn will not land), armored (steel hex — bring shred or AP), burrowed (dashed ring + UNTARGETABLE), hit confirm (brass flash), mark (gold brackets). Same 40 px footprint so nothing jumps.',
  render: () => `${world()}<div class="scrim-bottom"></div>${['default', 'shielded', 'armored', 'burrowed', 'hit', 'mark'].map((s, i) => `<div class="abs" style="left:${260 + (i % 3) * 560}px;top:${240 + Math.floor(i / 3) * 400}px;width:400px;height:300px;background:rgba(19,25,38,.55);box-shadow:inset 0 0 0 1px var(--border-panel);clip-path:var(--clip-chamfer)"><div class="abs" style="left:0;right:0;top:0;height:34px;display:flex;align-items:center;padding:0 14px;background:var(--obsidian-600)"><span class="label" style="color:var(--text-secondary)">${s}</span></div><div class="abs" style="inset:34px 0 0 0">${crosshair(s)}</div></div>`).join('')}` });

S({ id: 'overheads', group: 'In-match', label: 'World overheads', tag: 'hp · shield · status', note: 'HP bar (4 px, threat-red under 30%), shield bar stacked above, status chips left-to-right by channel, elite tag above the name. Scales with distance; below 6 px the bar collapses to a dot.',
  render: () => `${world()}<div class="scrim-bottom"></div>${[
    ['Drifter · burn', { hp: 62, status: ['burn'] }], ['Warden · shielded', { hp: 100, shield: 100, name: 'Warden' }], ['Aegis · shred + mark', { hp: 55, status: ['shred', 'mark'], name: 'Aegis' }], ['Monolith · elite juggernaut', { hp: 100, name: 'Monolith', elite: 'juggernaut' }],
    ['Mote swarm · chill', { hp: 30, status: ['chill'] }], ['Skiff · low', { hp: 18, name: 'Skiff' }], ['Cluster · elite swift', { hp: 80, name: 'Cluster', elite: 'swift' }], ['Frozen', { hp: 45, status: ['freeze', 'shock'], name: 'Drifter' }],
  ].map(([t, o], i) => `<div class="abs" style="left:${160 + (i % 4) * 420}px;top:${230 + Math.floor(i / 4) * 380}px;width:340px;height:280px;background:rgba(19,25,38,.55);box-shadow:inset 0 0 0 1px var(--border-panel);clip-path:var(--clip-chamfer)"><div class="abs" style="left:0;right:0;top:0;height:34px;display:flex;align-items:center;padding:0 14px;background:var(--obsidian-600)"><span class="label" style="color:var(--text-secondary)">${t}</span></div>${overhead({ ...o, x: 170, y: 190, scale: 2.2 })}</div>`).join('')}` });

S({ id: 'prompts', group: 'In-match', label: 'Interaction prompts', tag: '8', note: 'One chamfered glass chip per interactable: key cap, verb, object, optional cost/state. Hold actions fill the chip left-to-right. Barricade cost shows the Forge discount struck through.',
  render: () => `${world()}<div class="scrim-bottom"></div><div class="abs col" style="left:50%;top:50%;transform:translate(-50%,-50%);gap:14px;align-items:center">
    <div class="toast brass" style="font-size:var(--size-body)">${kbd('E')} <b>Build</b> · socket g4 · ground</div>
    <div class="toast" style="font-size:var(--size-body)">${kbd('E')} <b>Upgrade</b> Lance · L3 → L4 <span class="brass mono">80</span></div>
    <div class="toast" style="font-size:var(--size-body)">${kbd('E')} <b>Barricade</b> · b1 <span class="mono muted" style="text-decoration:line-through">60</span> <span class="brass mono">54</span> <span class="tag brass">forge</span></div>
    <div class="toast ok" style="font-size:var(--size-body);position:relative;overflow:hidden"><div class="abs" style="left:0;top:0;bottom:0;width:62%;background:rgba(123,192,67,.18)"></div>${kbd('R')} <b>Hold</b> · Revive Vane <span class="mono ok">62%</span></div>
    <div class="toast" style="font-size:var(--size-body)">${kbd('E')} <b>Ride</b> zipline → core gate</div>
    <div class="toast" style="font-size:var(--size-body)">${kbd('E')} <b>Armory</b> · gunsmith</div>
    <div class="toast" style="font-size:var(--size-body)">${kbd('F')} <b>Start wave early</b> <span class="brass mono">+40 scrap</span></div>
    <div class="toast dan" style="font-size:var(--size-body)">${kbd('E')} <b>Repair</b> Barricade <span class="mono danger">34%</span> · wrench</div>
  </div>` });

S({ id: 'revive', group: 'In-match', label: 'Revive beacon + downed', tag: 'both sides', note: 'Downed player: red vignette, greyed world, bleed-out ring, spectate strip, "hold R" from a teammate advances the ring. Beacon in the world: green column + progress ring above the body, visible through walls.',
  render: () => `<div class="grey">${world()}</div><div class="vignette-red"></div><div class="scrim-bottom"></div>${hudTop({ alive: 9 })}
    <div class="abs" style="left:1180px;top:520px;transform:translate(-50%,-100%)"><div class="progress-ring" style="--p:62%"><div><span class="stat mono ok">62%</span></div></div><div style="width:2px;height:120px;background:linear-gradient(rgba(123,192,67,.8),transparent);margin:0 auto"></div></div>
    <div class="abs col" style="left:50%;top:50%;transform:translate(-50%,-50%);align-items:center;gap:18px">
      <span class="label danger" style="font-size:var(--size-caption)">Downed</span><h1 class="h1">Bleeding out</h1>
      <div class="row" style="gap:20px;align-items:center"><div class="progress-ring" style="--p:38%;background:conic-gradient(var(--threat-500) var(--p),var(--obsidian-500) 0);box-shadow:0 0 20px rgba(201,59,40,.4)"><div><span class="stat mono danger">14s</span></div></div>
      <div class="col" style="gap:6px"><span style="font-size:var(--size-body-lg);color:var(--text-secondary)"><b style="color:var(--text-primary)">Vane</b> is reviving you</span>${bar(62, 'tall')}<span class="label">Teammate holds R · 3 s</span></div></div>
      <div class="row" style="gap:10px"><span class="btn sec">${kbd('←')} Spectate Kestrel</span><span class="btn sec">Spectate Vane ${kbd('→')}</span></div>
    </div>${hudVitals({ hp: 0 })}` });

S({ id: 'endless', group: 'In-match', label: 'Endless HUD', tag: 'wave 27', note: 'Endless swaps the wave pip strip for an open counter with the active elite tags and a threat multiplier; everything else stays where muscle memory expects it.',
  render: () => `${world()}${overhead({ x: 900, y: 470, hp: 62, elite: 'voltaic', status: ['shock'], name: 'Aegis' })}${overhead({ x: 1200, y: 440, hp: 100, elite: 'gilded', name: 'Monolith', scale: 1.1 })}<div class="scrim-top"></div><div class="scrim-bottom"></div>
    <div class="abs" style="left:0;right:0;top:0;height:var(--hud-topbar-h);display:flex;align-items:center;justify-content:center"><div class="glass row" style="padding:8px 18px;clip-path:var(--clip-notch-top);box-shadow:inset 0 0 0 1px var(--border-panel);gap:var(--space-7)">
      <div class="col" style="gap:2px;align-items:center"><span class="label">Wave</span><span class="numeral" style="color:var(--wave-boss)">27</span></div><div class="rule" style="width:1px;height:36px"></div>
      <div class="col" style="gap:4px"><span class="label">Elites this wave</span><div class="row" style="gap:6px"><span class="elite gilded">gilded</span><span class="elite voltaic">voltaic</span><span class="elite umbral">umbral</span></div></div><div class="rule" style="width:1px;height:36px"></div>
      <div class="col" style="gap:2px"><span class="label">Threat</span><span class="stat mono" style="color:var(--wave-boss)">×2.4</span></div><div class="rule" style="width:1px;height:36px"></div>
      <div class="col" style="gap:2px"><span class="label">Best</span><span class="stat mono muted">31</span></div></div></div>
    ${hudEconomy({ scrap: 1240, alloy: 14, flux: 9, plating: 6, gravium: 3 })}${hudTeam()}${hudVitals({ hp: 88, faction: 'tempest', ability: 'Chain Surge', cd: 40 })}${hudLoadout({ weapon: 'scattergun', ammoType: 'incendiary', mag: 5, magMax: 8, reserve: 40, alt: 'PUMP', sel: 1, slots: ['sidearm', 'scattergun'] })}${crosshair()}` });

/* ── Build ─────────────────────────────────────────────────────────── */
S({ id: 'wheel', group: 'Build', label: 'Build wheel', tag: 'radial', note: 'Radial, socket-tag filtered: on a ground socket the wall-only entries dim, Barricade only appears on b-sockets. Hub shows the socket id and scrap; the ghost + range sphere render in the world behind. Forge discount is applied in the cost readout.',
  render: () => `${world(`<div class="range" style="left:50%;top:57%;width:520px;height:520px;margin:-260px 0 0 -260px"></div><div class="ghost" style="left:50%;top:57%;margin:-170px 0 0 -60px"></div>`)}<div class="scrim-top"></div><div class="scrim-bottom"></div>${hudTop()}${hudEconomy()}
    <div class="wheel">${TOWERS.map((t, i) => { const a = (i / 6) * Math.PI * 2 - Math.PI / 2, x = Math.cos(a) * 205, y = Math.sin(a) * 205; const off = t.id === 'barricade'; return `<div class="seg ${i === 0 ? 'sel' : ''} ${off ? 'off' : ''}" style="transform:translate(${x}px,${y}px)">${ic('tower_' + t.id, i === 0 ? 'brass' : '')}<span class="nm">${t.name}</span><span class="cost">${off ? '—' : Math.round(t.cost * .9)}</span><span class="label" style="font-size:9px">${t.tag}</span></div>`; }).join('')}
      <div class="hub"><div class="col" style="gap:4px;align-items:center"><span class="label">Socket</span><span class="stat mono">g4</span><span class="tag ok">ground</span><span class="label" style="margin-top:4px">Range 18 m</span></div></div></div>
    <div class="abs" style="left:50%;bottom:150px;transform:translateX(-50%)"><div class="panel glass" style="width:460px"><div class="hd brass"><span class="ic"></span><h3>Lance · L1</h3><span class="tag brass">100 → 90</span></div><div class="bd col" style="gap:8px"><span style="font-size:var(--size-caption);color:var(--text-secondary)">${TOWERS[0].desc}</span><div class="row" style="gap:16px"><span class="label">DMG <b class="mono" style="color:var(--text-primary)">14</b></span><span class="label">RATE <b class="mono" style="color:var(--text-primary)">1.6/s</b></span><span class="label">RANGE <b class="mono" style="color:var(--text-primary)">18 m</b></span><span class="label">HITS <b class="mono" style="color:var(--text-primary)">ground · air</b></span></div><div class="row" style="gap:8px;margin-top:4px"><span class="btn">Place ${kbd('LMB')}</span><span class="btn sec">Cancel ${kbd('Esc')}</span></div></div></div></div>` });

S({ id: 'upgrade', group: 'Build', label: 'Upgrade panel', tag: '3 paths', note: 'Three paths × ten level pips; breakpoints (L3/L7/L10) are brass pips with their recipe shown. Next-level cost + stat delta per path; sell refund in the footer. The lit module column on the tower mirrors the pip you hover.',
  render: () => `${world(`<div class="range" style="left:50%;top:57%;width:640px;height:640px;margin:-320px 0 0 -320px"></div>`)}<div class="scrim-top"></div><div class="scrim-bottom"></div>${hudTop()}${hudEconomy()}
    <div class="abs" style="right:var(--hud-edge);top:90px;width:520px">${panel('Lance · socket g4', `
      <div class="col" style="gap:18px">
        ${[['damage', 'Damage', 4, ['Alloy 3 → +pierce', 'Plating 2 → AP rounds', 'Gravium 1 → rail overcharge'], '+2 dmg', 60], ['range', 'Range', 2, ['Flux 2 → +4 m', 'Alloy 4 → sightline relay', 'Flux 5 → global mark'], '+1.5 m', 45], ['rate', 'Rate', 7, ['Alloy 2 → dual feed', 'Flux 3 → capacitor', 'Gravium 2 → auto-loader'], '+0.15/s', 110]].map(([id, n, lvl, bps, d, cost], i) => `
        <div class="card ${i === 0 ? 'sel' : ''}"><div class="row" style="gap:12px">${ic('path_' + id, i === 0 ? 'brass' : '')}<div class="grow col" style="gap:6px"><div class="row between"><span style="font:var(--weight-bold) var(--size-body)/1 var(--font-display);text-transform:uppercase;letter-spacing:var(--tracking-label)">${n}</span><span class="mono" style="font-size:var(--size-caption);color:var(--text-secondary)">L${lvl} <span class="muted">→</span> L${lvl + 1} <span class="ok">${d}</span></span></div>${pips(lvl)}
        <div class="row" style="gap:6px;flex-wrap:wrap">${bps.map((b, k) => `<span class="tag ${lvl >= [3, 7, 10][k] ? 'brass' : ''}">L${[3, 7, 10][k]} · ${b}</span>`).join('')}</div></div>
        <div class="col" style="gap:6px;align-items:flex-end"><span class="btn ${i === 0 ? '' : 'sec'} sm">Upgrade <kbd>${i + 1}</kbd></span><span class="stat mono brass" style="font-size:var(--size-stat-sm)">${cost}</span></div></div></div>`).join('')}
        <div class="rule"></div>
        <div class="row" style="gap:20px"><span class="label">Kills <b class="mono" style="color:var(--text-primary)">128</b></span><span class="label">DMG dealt <b class="mono" style="color:var(--text-primary)">3,940</b></span><span class="label">Uptime <b class="mono" style="color:var(--text-primary)">94%</b></span><span class="label">Coverage <b class="mono arcane">ground 62% · air 40%</b></span></div>
      </div>`, { tone: 'brass', ft: `<div class="row between"><span class="label">Invested <b class="mono" style="color:var(--text-primary)">310</b> · sell refunds 70%</span><span class="btn dan sm">Sell · 217 <kbd>X</kbd></span></div>` })}</div>` });

/* ── Armory ────────────────────────────────────────────────────────── */
S({ id: 'armory', group: 'Armory', label: 'Armory / gunsmith', tag: '7 slots', note: 'Left: platform rail. Centre: the 7-slot grid around the gun, each slot showing the mounted module. Right: stat-delta bars (brass tick = base, green/red fill = built) and the recipe cost. Bottom: ammo type and blueprint recraft.',
  render: () => `<div class="abs" style="inset:0;background:var(--obsidian-900)"></div><div class="abs gridbg" style="inset:0;opacity:.6"></div>
    <div class="abs" style="left:0;right:0;top:0;height:64px;display:flex;align-items:center;gap:24px;padding:0 32px;background:var(--surface-panel);border-bottom:2px solid var(--brass-500)"><h1 class="h2">Armory</h1><span class="tag brass">Gunsmith</span><span class="grow"></span>${hudEconomy().replace('class="abs" style="left:var(--hud-edge);top:var(--hud-edge)"', 'style="position:static"')}<span class="btn sec">Close ${kbd('Esc')}</span></div>
    <div class="abs col" style="left:32px;top:96px;width:300px;gap:10px">${[['sidearm', 'Sidearm', 'owned', 0], ['rifle', 'Rifle', 'equipped', 120], ['scattergun', 'Scattergun', 'buy', 100], ['emberpistol', 'Ember pistol', 'buy', 90], ['wrench', 'Wrench', 'tool', 0]].map(([id, n, st, c]) => `<div class="card ${st === 'equipped' ? 'sel' : ''} row" style="gap:12px">${ic('weapon_' + id, st === 'equipped' ? 'brass' : '')}<div class="grow col" style="gap:2px"><span style="font:var(--weight-bold) var(--size-body)/1 var(--font-display);text-transform:uppercase;letter-spacing:.06em">${n}</span><span class="label">${st === 'buy' ? 'Scrap ' + c : st}</span></div>${st === 'buy' ? `<span class="btn sm">Buy</span>` : st === 'equipped' ? tag('1', 'arc') : ''}</div>`).join('')}</div>
    <div class="abs" style="left:360px;top:96px;width:900px;height:640px;background:rgba(19,25,38,.5);box-shadow:inset 0 0 0 1px var(--border-panel);clip-path:var(--clip-chamfer)">
      <div class="abs" style="left:150px;top:230px;width:600px;height:170px;background:var(--obsidian-500);clip-path:polygon(0 40%,10% 40%,12% 25%,60% 25%,62% 0,100% 0,100% 55%,85% 55%,80% 100%,70% 100%,68% 55%,30% 55%,25% 80%,15% 80%,12% 55%,0 55%);box-shadow:inset 0 0 0 1px var(--border-strong)"></div>
      ${[['barrel', 'Long barrel', 'longbarrel', 150, 120, 1], ['muzzle', 'Compensator', 'compensator', 40, 200, 1], ['optic', 'Rangefinder', 'rangefinder', 420, 110, 1], ['magazine', 'Drum feed', 'drumfeed', 560, 480, 1], ['stock', 'Brace stock', 'bracestock', 780, 200, 1], ['underbarrel', 'empty', '', 330, 480, 0], ['infusion', 'Volt cap', 'voltcap', 780, 480, 1]].map(([slot, n, id, x, y, on]) => `
        <div class="abs col" style="left:${x}px;top:${y}px;align-items:center;gap:4px"><div class="slot lg ${on ? 'sel' : 'empty'}">${on ? ic('attach_' + id, 'arc') : ''}</div><span class="label" style="color:var(--text-secondary)">${slot}</span><span style="font-size:var(--size-micro);color:${on ? 'var(--text-arcane)' : 'var(--text-disabled)'}">${n}</span></div>`).join('')}
      <div class="abs" style="left:0;right:0;bottom:0;height:60px;display:flex;align-items:center;gap:18px;padding:0 20px;background:var(--surface-inset);border-top:1px solid var(--border-panel)"><span class="label">Ammo</span>${['standard', 'ap', 'hollowpoint', 'incendiary', 'cryo'].map((a, i) => `<span class="row" style="gap:6px;padding:4px 8px;box-shadow:inset 0 0 0 1px ${i === 1 ? 'var(--brass-500)' : 'var(--border-panel)'}">${ic('ammo_' + a, i === 1 ? 'brass' : '')}<span class="label" style="color:${i === 1 ? 'var(--text-accent)' : 'var(--text-secondary)'}">${a}</span></span>`).join('')}</div>
    </div>
    <div class="abs col" style="left:1290px;top:96px;width:598px;gap:12px">${panel('Rifle · built', `<div class="col" style="gap:14px">
      ${[['Damage', 11, 13.9, 1.26], ['Rate', 2.2, 2.28, 1.04], ['Range', 80, 120, 1.5], ['Handling', 60, 52, .87]].map(([n, b, v, f]) => `<div class="col" style="gap:5px"><div class="row between"><span class="label">${n}</span><span class="mono" style="font-size:var(--size-caption)"><span class="muted">${b}</span> → <b style="color:${f >= 1 ? 'var(--state-success)' : 'var(--state-danger)'}">${v}</b> <span class="muted">×${f.toFixed(2)}</span></span></div><div class="bar tall delta ${f >= 1 ? 'up' : 'down'}"><i style="width:${Math.min(100, f * 50)}%"></i><b class="base" style="left:50%"></b></div></div>`).join('')}
      <div class="rule"></div><div class="row between"><span class="label">Applies</span><span class="row" style="gap:6px">${tag('mark', 'brass')}${tag('shock', 'soul')}</span></div>
      <div class="row between"><span class="label">Tracer</span><span class="row" style="gap:6px">${ic('ammo_ap')}<span class="mono" style="font-size:var(--size-caption)">AP · ignores flat armor</span></span></div></div>`, { tone: 'arcane' })}
      ${panel('Recipe · Volt cap', `<div class="row between"><span class="row" style="gap:10px">${ic('scrap_flux')}<span class="mono">Flux 5</span><span class="muted mono">/ 3 owned</span></span><span class="btn" disabled>Craft</span></div>`, { hazard: true })}
      ${panel('Blueprint', `<div class="row between"><div class="col" style="gap:2px"><span style="font:var(--weight-bold) var(--size-body)/1 var(--font-display)">MARKSMAN B</span><span class="label">Rifle · 6 modules · saved wave 7</span></div><div class="row" style="gap:8px"><span class="btn sec sm">Save current</span><span class="btn arc sm">Recraft · 14 alloy</span></div></div>`)}</div>` });

/* ── Lobby ─────────────────────────────────────────────────────────── */
S({ id: 'lobby', group: 'Lobby', label: 'Lobby + faction menu', tag: 'M2', note: 'Three faction columns — one per player, duplicates refused ("factionTaken" pushes you to the free one). Level 1–5 curve per faction (cooldown/radius/magnitude), variant slot, ready state. Sector select lives on the next tab.',
  render: () => `<div class="abs" style="inset:0;background:var(--obsidian-900)"></div><div class="abs gridbg" style="inset:0;opacity:.6"></div>
    <div class="abs" style="left:0;right:0;top:0;height:64px;display:flex;align-items:center;gap:24px;padding:0 32px;background:var(--surface-panel);border-bottom:2px solid var(--brass-500)"><h1 class="h2">Lobby</h1><span class="tag">Code <b class="mono">KX7-2Q</b></span><span class="tag ok">3 / 3 joined</span><span class="grow"></span><span class="tabs" style="margin:0"><button aria-pressed="true">Factions</button><button>Sector</button><button>Loadout</button></span><span class="btn sec">Leave</span></div>
    <div class="abs" style="left:32px;right:32px;top:96px;bottom:110px;display:grid;grid-template-columns:repeat(3,1fr);gap:20px">${FACTIONS.map((f, i) => { const lvl = [3, 5, 1][i], me = i === 1, taken = i === 0; return `
      <section class="panel" style="${me ? 'box-shadow:inset 0 0 0 1px var(--brass-500),var(--glow-brass)' : ''}"><div class="hd ${me ? 'brass' : ''}"><span class="faction ${f.id}" style="width:10px;height:10px"></span><h3>${f.name}</h3>${taken ? tag('taken · Kestrel', 'dan') : me ? tag('you', 'brass') : tag('open')}</div>
      <div class="bd col" style="gap:16px">
        <div style="height:220px;background:var(--surface-inset);box-shadow:inset 0 0 0 1px var(--border-panel);display:grid;place-items:center;position:relative"><span class="label">hero_${f.id}.glb</span><div class="abs" style="left:14px;bottom:12px;color:${f.hue}">${ic('faction_' + f.id)}</div></div>
        <div class="row between"><div class="col" style="gap:2px"><span class="h3">${f.ability}</span><span class="label">Q · ${f.cd} s · ${f.r} m</span></div><div class="col" style="gap:2px;align-items:flex-end"><span class="label">Passive</span><span class="mono" style="font-size:var(--size-caption)">${f.passive}</span></div></div>
        <div class="col" style="gap:6px"><div class="row between"><span class="label">Level ${lvl} / 5</span><span class="mono" style="font-size:var(--size-caption)">${lvl * 100 - 40} / ${lvl * 100} xp</span></div>${bar(60, 'xp')}</div>
        <div class="col" style="gap:8px"><span class="label">Level curve</span><div class="curve"><svg viewBox="0 0 100 40" preserveAspectRatio="none"><polyline fill="none" stroke="var(--arcane-400)" stroke-width="1.2" points="0,34 25,30 50,26 75,22 100,18"/><polyline fill="none" stroke="var(--brass-400)" stroke-width="1.2" points="0,34 25,28 50,22 75,16 100,10"/><polyline fill="none" stroke="var(--soul-400)" stroke-width="1.2" points="0,34 25,32 50,30 75,28 100,26"/><line x1="${(lvl - 1) * 25}" y1="0" x2="${(lvl - 1) * 25}" y2="40" stroke="var(--steel-300)" stroke-dasharray="2 2"/></svg></div>
        <div class="row" style="gap:12px"><span class="label" style="color:var(--arcane-400)">— cooldown ×${Math.pow(.94, lvl - 1).toFixed(2)}</span><span class="label" style="color:var(--brass-400)">— radius ×${(1 + .06 * (lvl - 1)).toFixed(2)}</span><span class="label" style="color:var(--soul-400)">— magnitude ×${(1 + .05 * (lvl - 1)).toFixed(2)}</span></div></div>
        <div class="row between"><span class="label">Variant slot</span><div class="row" style="gap:6px"><div class="slot ${me ? 'sel' : 'empty'}" style="width:40px;height:40px">${me ? ic('ability_' + f.ability.toLowerCase().replace(' ', ''), 'arc') : ''}</div><span style="font-size:var(--size-caption);color:var(--text-secondary)">${me ? 'Wide Wave · +2 m, −10% burn' : 'Unlocks at L2'}</span></div></div>
      </div><div class="ft row between"><span class="label">${taken ? 'Kestrel · ready' : me ? 'Vane (you)' : 'Rook · picking'}</span>${taken ? tag('ready', 'ok') : me ? `<span class="btn sm">Ready ${kbd('Space')}</span>` : `<span class="btn sec sm" disabled>Waiting</span>`}</div></section>`; }).join('')}</div>
    <div class="abs" style="left:32px;right:32px;bottom:32px;height:60px;display:flex;align-items:center;gap:16px;padding:0 20px;background:var(--surface-panel);box-shadow:inset 0 0 0 1px var(--border-panel);clip-path:var(--clip-chamfer)"><span class="label">Sector</span><span style="font:var(--weight-bold) var(--size-body)/1 var(--font-display)">FOUNDRY · 10 waves</span><span class="tag ember">cond · none</span><span class="grow"></span><span class="label">Host starts when all ready · 2 / 3</span><span class="btn lg" disabled>Launch</span></div>` });

S({ id: 'sector', group: 'Lobby', label: 'Sector select', tag: 'maps', note: 'Card per sector with route sketch, wave count, best clear, and the condition banner rolling for this run. Switchyard shows the barricade lesson callout. Endless is a mode toggle on the selected sector.',
  render: () => `<div class="abs" style="inset:0;background:var(--obsidian-900)"></div><div class="abs gridbg" style="inset:0;opacity:.6"></div>
    <div class="abs" style="left:0;right:0;top:0;height:64px;display:flex;align-items:center;gap:24px;padding:0 32px;background:var(--surface-panel);border-bottom:2px solid var(--brass-500)"><h1 class="h2">Sector select</h1><span class="grow"></span><span class="tabs" style="margin:0"><button>Factions</button><button aria-pressed="true">Sector</button><button>Loadout</button></span><span class="btn sec">Back</span></div>
    <div class="abs" style="left:32px;right:32px;top:96px;bottom:110px;display:grid;grid-template-columns:repeat(3,1fr);gap:20px">${[
      ['Test Lane', 'M0 · 3 waves', 'One S-curve. The harness fixture.', 'M-30,0 L-12,0 L-12,10 L8,10 L8,-6 L30,-6', false, 'clear 0:58', ''],
      ['Foundry', 'M1 · 10 waves', 'Two tiers, ground lane under the catwalk, air lane overhead. Wall sockets on the deck.', 'M-40,0 L-20,0 L-20,14 L0,14 L0,-8 L18,-8 L18,6 L36,6', true, 'best wave 10 · 12:40', 'none'],
      ['Switchyard', 'M2 · 12 waves', 'Three tiers. The freight cut is fast and badly covered — barricade b1 closes it.', 'M-45,-10 L-25,-10 L-25,12 L-5,12 L-5,-12 L15,-12 L15,10 L40,8', false, 'best wave 9', 'fog'],
    ].map(([n, sub, d, path, sel, best, cond], i) => `<section class="panel" style="${sel ? 'box-shadow:inset 0 0 0 1px var(--brass-500),var(--glow-brass)' : ''}"><div class="hd ${sel ? 'brass' : ''}"><span class="ic"></span><h3>${n}</h3>${tag(sub)}</div>
      <div class="bd col" style="gap:14px"><div style="height:300px;background:var(--surface-inset);box-shadow:inset 0 0 0 1px var(--border-panel);position:relative;background-image:var(--tex-grid)"><svg viewBox="-55 -25 110 50" style="position:absolute;inset:20px;width:calc(100% - 40px);height:calc(100% - 40px)"><path d="${path}" fill="none" stroke="var(--brass-400)" stroke-width="1.6"/>${i === 2 ? '<path d="M-45,-10 L-20,-2 L5,0 L40,8" fill="none" stroke="var(--threat-400)" stroke-width="1.2" stroke-dasharray="2 2"/><rect x="-10" y="-3" width="4" height="4" fill="var(--threat-400)"/>' : ''}${i === 1 ? '<path d="M-40,-6 L-10,-2 L14,4 L36,5" fill="none" stroke="var(--arcane-400)" stroke-width="1" stroke-dasharray="1.5 1.5"/>' : ''}</svg>${cond ? `<div class="abs" style="left:10px;top:10px" >${tag('cond · ' + cond, cond === 'none' ? '' : 'soul')}</div>` : ''}</div>
      <p style="margin:0;font-size:var(--size-caption);color:var(--text-secondary);line-height:var(--leading-normal)">${d}</p>${i === 2 ? `<div class="toast dan">${kbd('!')} <b>Barricade lesson</b> · the short route needs b1</div>` : ''}<div class="row between"><span class="label">${best}</span>${sel ? `<span class="row" style="gap:8px"><span class="label">Endless</span><span class="toggle"></span></span>` : ''}</div></div>
      <div class="ft row between"><span class="label">${['4 sockets', '12 sockets · 4 stations', '16 sockets · 5 stations'][i]}</span>${sel ? `<span class="btn sm">Selected</span>` : `<span class="btn sec sm">Select</span>`}</div></section>`).join('')}</div>
    <div class="abs" style="left:32px;right:32px;bottom:32px;height:60px;display:flex;align-items:center;gap:16px;padding:0 20px;background:var(--surface-panel);box-shadow:inset 0 0 0 1px var(--border-panel);clip-path:var(--clip-chamfer)"><span class="label">Selected</span><span style="font:var(--weight-bold) var(--size-body)/1 var(--font-display)">FOUNDRY · 10 waves · standard</span><span class="grow"></span><span class="btn lg">Confirm sector</span></div>` });

/* ── Between waves ─────────────────────────────────────────────────── */
S({ id: 'intermission', group: 'Between waves', label: 'Intermission panel', tag: '18 s', note: 'Next-wave preview: enemy composition by lane with counts and the new-type callout, condition banner, income summary, countdown with F to start early (+scrap). Sits top-centre so the HUD stays usable while you build.',
  render: () => `${world()}<div class="scrim-top"></div><div class="scrim-bottom"></div>${hudTop({ phase: 'BUILD', timer: '0:18', alive: 0 })}${hudEconomy({ scrap: 520 })}${hudTeam()}${hudVitals({ hp: 100 })}${hudLoadout()}
    <div class="abs" style="left:50%;top:90px;transform:translateX(-50%);width:820px">${panel('Next · Wave 5 of 10', `<div class="col" style="gap:16px">
      <div class="row" style="gap:12px;padding:10px 12px;background:rgba(155,91,232,.12);box-shadow:inset 0 0 0 1px var(--soul-500)">${tag('condition', 'soul')}<span style="font:var(--weight-bold) var(--size-body)/1 var(--font-display)">FOG</span><span style="font-size:var(--size-caption);color:var(--text-secondary)">Tower range −25% · Detector reveals · sightline relays matter</span></div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px">
        <div class="col" style="gap:8px"><span class="label">Ground lane</span>${[['drifter', 14, ''], ['aegis', 4, 'new'], ['mole', 3, ''], ['cluster', 2, '']].map(([e, n, nw]) => `<div class="row between" style="padding:6px 8px;background:var(--surface-inset)"><span class="row" style="gap:8px">${ic('enemy_' + e)}<span style="text-transform:capitalize">${e}</span>${nw ? tag('new', 'dan') : ''}</span><span class="stat mono" style="font-size:var(--size-stat-sm)">×${n}</span></div>`).join('')}</div>
        <div class="col" style="gap:8px"><span class="label">Air lane</span>${[['skiff', 6, '']].map(([e, n]) => `<div class="row between" style="padding:6px 8px;background:var(--surface-inset)"><span class="row" style="gap:8px">${ic('enemy_' + e)}<span style="text-transform:capitalize">${e}</span></span><span class="stat mono" style="font-size:var(--size-stat-sm)">×${n}</span></div>`).join('')}
          <div class="card col" style="gap:6px;margin-top:4px"><span class="label brass">Aegis</span><span style="font-size:var(--size-caption);color:var(--text-secondary)">140° front plate ×0.25 · rear ×1.5. Flank it or shred it.</span><div class="row" style="gap:6px">${tag('shred')}${tag('wall sockets')}${tag('ap ammo')}</div></div></div></div>
      <div class="rule"></div>
      <div class="row between"><span class="row" style="gap:18px"><span class="label">Wave 4 income <b class="mono brass">+180</b></span><span class="label">Scrap drops <b class="mono" style="color:var(--text-primary)">alloy 3 · flux 1</b></span><span class="label">Leaks <b class="mono ok">0</b></span></span><span class="btn">Start now ${kbd('F')} <span class="mono">+40</span></span></div></div>`, { tone: 'brass', hazard: true })}</div>` });

S({ id: 'endmatch', group: 'Between waves', label: 'End-of-match stats', tag: 'victory', note: 'Hero title (VICTORY / CORE LOST), per-player columns with damage / kills / builds / revives, tower MVP, reaction count, wave timeline sparkline, XP gained per faction, scrap banked for the profile. Rematch and lobby actions.',
  render: () => `<div class="grey">${world()}</div><div class="abs" style="inset:0;background:var(--surface-overlay)"></div>
    <div class="abs col" style="left:50%;top:60px;transform:translateX(-50%);align-items:center;gap:6px"><span class="label brass" style="font-size:var(--size-caption)">Foundry · 10 waves · 12:40</span><h1 class="hero-t brass">VICTORY</h1><span class="label">Core intact · 3 / 3 · 0 leaks</span></div>
    <div class="abs" style="left:120px;right:120px;top:260px;display:grid;grid-template-columns:1.3fr 1fr;gap:20px">
      ${panel('Squad', `<table class="data"><thead><tr><th>Player</th><th style="text-align:right">Damage</th><th style="text-align:right">Kills</th><th style="text-align:right">Builds</th><th style="text-align:right">Reactions</th><th style="text-align:right">Revives</th><th style="text-align:right">XP</th></tr></thead><tbody>
        ${[['forge', 'Kestrel', 18420, 96, 14, 21, 2, 140], ['ember', 'Vane', 24110, 131, 3, 38, 1, 160], ['tempest', 'Rook', 15870, 88, 5, 17, 3, 120]].map(([f, n, d, k, b, r, rv, xp]) => `<tr><td><span class="row" style="gap:8px"><span class="faction ${f}"></span><b>${n}</b></span></td><td class="num">${d.toLocaleString()}</td><td class="num">${k}</td><td class="num">${b}</td><td class="num">${r}</td><td class="num">${rv}</td><td class="num brass">+${xp}</td></tr>`).join('')}</tbody></table>
        <div class="row" style="gap:16px;margin-top:16px">${[['Tower MVP', 'Lance · g4', '3,940 dmg'], ['Best reaction', 'Thermal Shock', '×41'], ['Scrap banked', '+1,240', 'alloy 9 · flux 4 · plating 2']].map(([l, v, s]) => `<div class="card grow col" style="gap:4px"><span class="label">${l}</span><span style="font:var(--weight-bold) var(--size-body-lg)/1 var(--font-display)">${v}</span><span class="mono muted" style="font-size:var(--size-micro)">${s}</span></div>`).join('')}</div>`, { tone: 'brass' })}
      <div class="col" style="gap:20px">${panel('Wave timeline', `<div class="spark">${[12, 18, 20, 26, 31, 28, 40, 44, 52, 70].map((v, i) => `<i style="height:${v}%" class="${i === 9 ? 'hi' : ''}"></i>`).join('')}</div><div class="row between" style="margin-top:6px"><span class="label">w1</span><span class="label">clear time per wave</span><span class="label">w10</span></div>`)}
      ${panel('Faction XP', FACTIONS.map((f, i) => `<div class="col" style="gap:4px;margin-bottom:10px"><div class="row between"><span class="row" style="gap:6px"><span class="faction ${f.id}"></span><span class="label" style="color:var(--text-secondary)">${f.name} · L${[3, 5, 1][i]}${i === 2 ? ' → L2' : ''}</span></span><span class="mono" style="font-size:var(--size-caption)">+${[140, 160, 120][i]}</span></div>${bar([80, 100, 20][i], 'xp')}</div>`).join(''), { tone: 'arcane' })}
      <div class="row" style="gap:10px"><span class="btn lg grow">Rematch</span><span class="btn sec lg grow">Lobby</span><span class="btn ghost lg">Quit</span></div></div></div>` });

/* ── Menus ─────────────────────────────────────────────────────────── */
S({ id: 'pause', group: 'Menus', label: 'Pause / settings', tag: 'overlay', note: 'Scrim over the live game (multiplayer keeps running — the header says so). Left rail of sections, right pane of settings using field / toggle / slider controls. Sensitivity and FOV are numerals first.',
  render: () => `${world()}<div class="abs" style="inset:0;background:var(--surface-scrim)"></div>
    <div class="abs" style="left:50%;top:50%;transform:translate(-50%,-50%);width:1100px;height:720px" >${panel('Paused · match continues', `<div style="display:grid;grid-template-columns:240px 1fr;gap:24px;height:100%">
      <div class="col" style="gap:4px">${['Resume', 'Controls', 'Video', 'Audio', 'Accessibility', 'Network', 'How to play', 'Leave match'].map((s, i) => `<button class="btn ${i === 2 ? 'sec' : 'ghost'}" style="justify-content:flex-start;height:40px;${i === 7 ? 'color:var(--state-danger)' : ''}">${s}</button>`).join('')}</div>
      <div class="col" style="gap:14px">
        <span class="h3">Video</span>
        <div class="row between"><span>Resolution</span><span class="field" style="width:260px">2560 × 1440 <span class="muted">▾</span></span></div>
        <div class="row between"><span>Display</span><span class="field" style="width:260px">Borderless <span class="muted">▾</span></span></div>
        <div class="row between"><span>Field of view</span><span class="row" style="gap:12px;width:260px"><span class="slider grow"><i style="width:60%"></i><b style="left:60%"></b></span><span class="stat mono" style="font-size:var(--size-stat-sm);width:40px;text-align:right">96</span></span></div>
        <div class="row between"><span>HUD scale</span><span class="row" style="gap:12px;width:260px"><span class="slider grow"><i style="width:50%"></i><b style="left:50%"></b></span><span class="stat mono" style="font-size:var(--size-stat-sm);width:40px;text-align:right">1.0</span></span></div>
        <div class="row between"><span>Crosshair colour</span><span class="row" style="gap:6px">${['var(--steel-050)', 'var(--brass-400)', 'var(--arcane-400)', 'var(--venom-400)'].map((c, i) => `<i style="width:24px;height:24px;background:${c};box-shadow:inset 0 0 0 ${i === 0 ? 2 : 1}px ${i === 0 ? 'var(--arcane-400)' : 'var(--border-strong)'}"></i>`).join('')}</span></div>
        <div class="row between"><span>Screen shake</span><span class="toggle on"></span></div>
        <div class="row between"><span>Reduce flashes (reaction VFX)</span><span class="toggle"></span></div>
        <div class="row between"><span>Show teammate outlines</span><span class="toggle on"></span></div>
        <div class="rule"></div><span class="h3">Sensitivity</span>
        <div class="row between"><span>Mouse</span><span class="row" style="gap:12px;width:260px"><span class="slider grow"><i style="width:35%"></i><b style="left:35%"></b></span><span class="stat mono" style="font-size:var(--size-stat-sm);width:40px;text-align:right">3.5</span></span></div>
        <div class="row between"><span>ADS multiplier</span><span class="row" style="gap:12px;width:260px"><span class="slider grow"><i style="width:80%"></i><b style="left:80%"></b></span><span class="stat mono" style="font-size:var(--size-stat-sm);width:40px;text-align:right">0.8</span></span></div>
      </div></div>`, { ft: `<div class="row between"><span class="label">Build 0.2.1 · server tick 30 Hz · ping <b class="mono ok">24 ms</b></span><span class="row" style="gap:8px"><span class="btn sec sm">Defaults</span><span class="btn sm">Apply</span></span></div>`, style: 'height:100%' })}</div>` });

S({ id: 'howto', group: 'Menus', label: 'How-to-play cards', tag: '4 cards', note: 'Four cards, one idea each: build, shoot, react, hold the core. Big numeral, one icon cluster, two lines. Shown on first launch and from pause.',
  render: () => `<div class="abs" style="inset:0;background:var(--obsidian-900)"></div><div class="abs gridbg" style="inset:0;opacity:.6"></div>
    <div class="abs col" style="left:50%;top:80px;transform:translateX(-50%);align-items:center;gap:6px"><span class="label brass">How to play</span><h1 class="h1">Build. Shoot. React.</h1></div>
    <div class="abs cardsteps" style="left:120px;right:120px;top:240px">${[
      ['Build on sockets', 'Walk to a green ring, press E, pick a tower. Wall sockets on the deck see further. Barricades close shortcuts.', ['tower_lance', 'tower_nova', 'tower_barricade'], 'E'],
      ['Shoot what towers miss', 'Your gun is a tower that moves. Mark priority targets with right-click; flank Aegis; AP for armor.', ['weapon_rifle', 'ammo_ap', 'status_mark'], 'LMB'],
      ['React together', 'Chill from Singularity + burn from Ember = Thermal Shock. Chill + shock = Flash Freeze. Both halves needed.', ['status_chill', 'status_burn', 'reaction_thermalshock'], 'Q'],
      ['Hold the core', 'Every leak costs a core life. Revive with R. Start waves early for scrap when you are ready.', ['enemy_monolith', 'scrap_alloy', 'faction_forge'], 'R'],
    ].map(([t, d, icons, k], i) => `<section class="panel"><div class="hd"><span class="ic"></span><h3>Step ${i + 1}</h3>${kbd(k)}</div><div class="bd col" style="gap:14px;height:520px"><span class="stepnum">0${i + 1}</span><div style="height:180px;background:var(--surface-inset);box-shadow:inset 0 0 0 1px var(--border-panel);display:flex;align-items:center;justify-content:center;gap:18px">${icons.map((n) => ic(n, 'brass', 48)).join('')}</div><span class="h3">${t}</span><p style="margin:0;font-size:var(--size-body);color:var(--text-secondary);line-height:var(--leading-normal)">${d}</p></div></section>`).join('')}</div>
    <div class="abs row" style="left:50%;bottom:60px;transform:translateX(-50%);gap:10px"><span class="btn sec">Skip</span><span class="btn">Next ${kbd('→')}</span></div>` });

S({ id: 'connection', group: 'Menus', label: 'Connection / version / drop-in', tag: '5 states', note: 'Compact modal states: connecting, version mismatch (with both hashes), drop-in mid-match (joining at wave N), host migration, and the sim "factionTaken" refusal. Danger tone only when the player must act.',
  render: () => `<div class="grey">${world()}</div><div class="abs" style="inset:0;background:var(--surface-overlay)"></div>
    ${[
      ['Connecting', 'arcane', `<div class="col" style="gap:12px"><span style="font-size:var(--size-body-lg)">Joining <b>KX7-2Q</b> …</span>${bar(45, 'shield')}<span class="label">Handshake · 2 of 4 · 24 ms</span></div>`, `<span class="btn sec sm">Cancel</span>`],
      ['Version mismatch', 'danger', `<div class="col" style="gap:10px"><span style="font-size:var(--size-body-lg)">The host runs a different build.</span><div class="row" style="gap:14px"><span class="tag">you · <b class="mono">0.2.1 · a91f3c</b></span><span class="tag dan">host · <b class="mono">0.2.2 · 7be04d</b></span></div><span class="label">Sim determinism requires an exact match.</span></div>`, `<span class="btn sec sm">Back</span><span class="btn sm">Update</span>`],
      ['Drop-in', 'brass', `<div class="col" style="gap:10px"><span style="font-size:var(--size-body-lg)">Match in progress — joining at <b>wave 6 of 10</b>.</span><div class="row" style="gap:8px"><span class="faction forge"></span><span class="label">Forge taken</span><span class="faction ember"></span><span class="label">Ember taken</span><span class="faction tempest"></span><span class="label brass">Tempest open</span></div><span class="label">You spawn at the yard with the starter sidearm and 200 scrap.</span></div>`, `<span class="btn sec sm">Decline</span><span class="btn sm">Join as Tempest</span>`],
      ['Host migrating', '', `<div class="col" style="gap:10px"><span style="font-size:var(--size-body-lg)">Kestrel left. <b>Vane</b> is now host.</span>${bar(70, 'charge')}<span class="label">Rolling the sim back 12 ticks · match resumes automatically</span></div>`, ''],
      ['Faction taken', 'danger', `<div class="col" style="gap:10px"><span style="font-size:var(--size-body-lg)">Ember is already in this lobby.</span><span class="label">One faction per player — pick the other one.</span><div class="row" style="gap:8px"><span class="btn sm">Forge</span><span class="btn sm">Tempest</span></div></div>`, `<span class="btn sec sm">Back</span>`],
    ].map(([t, tone, body, ft], i) => `<div class="abs" style="left:${140 + (i % 3) * 560}px;top:${200 + Math.floor(i / 3) * 360}px;width:520px">${panel(t, body, { tone, ft: ft ? `<div class="row" style="gap:8px;justify-content:flex-end">${ft}</div>` : '' })}</div>`).join('')}` });
